insert into public.exam_questions (subject, question, options, answer) values ('정치', '''그리스도인''이라는 칭호는 누구에게 붙여집니까?', '["세례를 받은 자에게만 붙여진다.", "목회자에게만 붙여진다.", "교회 봉사자에게만 붙여진다.", "지교회에 등록하여 삼위일체 하나님을 믿는 자에게 붙여진다."]'::jsonb, 3);
