insert into public.exam_questions (subject, question, options, answer) values ('정치', '목사 공석 시 당회장은 누가 대행합니까?', '["당회 내 최고령 장로", "노회가 지정하는 목사", "교회의 수석 장로", "제직회장"]'::jsonb, 1);
