insert into public.exam_questions (subject, question, options, answer) values ('정치', '''천서를 접수, 호명한 후부터 회원권을 갖는다''는 규정의 목적은?', '["노회 진행을 지연시키기 위함", "노회원들에게 부담을 주기 위함", "총대 장로의 자격을 공식적으로 확인하고 질서를 유지하기 위함", "특정 장로에게 특혜를 주기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('정치', '총대 장로의 회원권 시작 시점이 중요한 이유는?', '["노회 회의의 공식적인 절차를 준수하고 그 결정에 대한 법적 효력을 부여하기 위함", "총대 장로의 개인적인 명예를 위함", "노회의 모든 안건을 신속하게 처리하기 위함", "노회원들의 참석률을 높이기 위함"]'::jsonb, 0);
