insert into public.exam_questions (subject, question, options, answer) values ('정치', '원로 장로가 가지는 특권 중 하나는?', '["노회 총대로 파송될 수 있다.", "당회장을 대행할 수 있다.", "당회 결의에 투표할 수 있다.", "당회의 언권 회원이 된다."]'::jsonb, 3);
