insert into public.exam_questions (subject, question, options, answer) values ('정치', '공동의회를 소집할 수 있는 조건 중 당회의 결정은?', '["당회장이 단독으로 결정할 때", "당회원 전원의 동의가 있을 때", "당회가 필요하다고 인정할 때", "당회의 결의 없이도 가능하다"]'::jsonb, 2);
