insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''악하지 아니할지라도 다른 사람으로 범죄하게 한 것''은 어떤 의미의 범죄입니까?', '["간접적인 영향으로 타인을 죄에 빠지게 한 것도 포함한다.", "직접적인 범죄만 해당한다.", "의도성이 없는 행동은 범죄로 보지 않는다.", "개인의 책임이 아니다."]'::jsonb, 0);
