insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''재판 혹 처벌 중에 있는 자''에 대하여 소송 접수를 신중히 고려해야 하는 이유는?', '["이미 다른 문제로 정신적, 법적 부담이 크기 때문", "재판 진행이 너무 쉬워지기 때문", "다른 재판에 영향을 주지 않기 위함", "그들의 죄를 면해주기 위함"]'::jsonb, 0);
