insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '죄증 설명서의 역할은 소장과 어떻게 다릅니까?', '["소장은 증거를 제시하고, 죄증 설명서는 죄상을 기록한다.", "죄증 설명서는 재판 후 작성된다.", "소장은 죄상을 기록하고, 죄증 설명서는 그 죄상의 증거를 제시한다.", "둘 다 동일한 역할을 한다."]'::jsonb, 2);
