insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '고소장은 무엇을 기록하여 무엇을 요구하는 소송 문서의 일종입니까?', '["범죄하였다는 죄상, 재판과 책벌", "재정 내역, 감사", "개인적인 불만, 사과", "선행 기록, 칭찬"]'::jsonb, 0);
