insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '고소장에 ''죄상''을 기록하는 것이 중요한 이유는?', '["죄를 증명할 필요가 없기 때문", "피고의 개인 정보를 노출하기 위함", "혐의의 구체성을 명시하여 재판의 초점을 분명히 하기 위함", "고소인의 감정을 표현하기 위함"]'::jsonb, 2);
