insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''이 밖에는 소송하는 자가 원고가 된다''는 규정은 무엇을 나타냅니까?', '["치리회가 아닌 경우, 고소를 제기하는 개인이 원고가 된다.", "모든 소송은 익명으로 진행된다.", "소송은 항상 치리회에 의해서만 시작된다.", "치리회만 원고가 될 수 있다."]'::jsonb, 0);
