insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판 안건이 되지 못하는 또 다른 경우는?', '["덕을 세움에 방해되는 경우", "교훈과 심술과 행위가 성경에 위반되는 경우", "권징조례로 금지할 일이 아니면", "다른 사람으로 범죄하게 한 경우"]'::jsonb, 2);
