insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '일반 행정을 치리하는 치리회가 재판 사건이 있을 때 재판회로 모이기로 가결 지을 때 재판 사건을 다루는 당석 재판은 무엇입니까?', '["상설 재판국", "특별재판국", "재판국", "재판회"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '치리회는 무엇을 조직하여 몇 사람에게 맡겨 재판 사건을 치리하게 하는 것입니까?', '["재판국", "제직회", "당회", "노회"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '기소 결정을 하는 주체는 누구입니까?', '["치리회", "제직회", "교인 전체", "당회장"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '기소 결정 시 신중함이 요구되는 주된 이유는?', '["기소 과정이 복잡하기 때문", "기소가 개인의 명예와 교회 전체에 미치는 영향이 크기 때문", "기소 비용이 많이 들기 때문", "기소 후에는 번복이 불가능하기 때문"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '기소가 결정되기 전에 치리회가 고려해야 할 사항은?', '["목사의 개인적인 판단만 따른다.", "빠른 처벌만을 목적으로 한다.", "교인의 의견만 반영한다.", "증거의 명확성, 범죄의 중대성, 교회의 덕을 종합적으로 고려해야 한다."]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '노회가 재판을 관할하는 대상은 누구입니까?', '["전도사, 권사", "목사, 목사후보생, 강도사", "장로, 집사", "서리 집사"]'::jsonb, 1);
