insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '목사후보생과 강도사의 ''신분상 관할''은 어디에서 받습니까?', '["당회", "교육기관", "노회", "총회"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '원피고와 증인 등을 처음 소환할 때, 소환 기간은 얼마 이상으로 두어야 합니까?', '["3 일 이상", "5 일 이상", "10 일 이상", "1 개월 이상"]'::jsonb, 2);
