insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '피고에게 소환장과 함께 첨부해야 하는 서류는?', '["고소장과 죄증 설명서 각 1 통", "재판국원 명단", "판결문", "참고인 진술서"]'::jsonb, 0);
