insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '원고 혹은 피고를 위해 변호하는 사람을 무엇이라고 합니까?', '["참관인", "증인", "대리인", "변호인"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '변호인이 될 수 있는 자격은? (총회 결정 포함)', '["누구나 가능하다.", "본 장로회 목사, 장로이어야 하며, 70 세 정년 은퇴자는 될 수 없다.", "법률 전문가만 가능하다.", "사건 당사자의 가족만 가능하다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '사건 당사자를 대리하는 자이며, 피고가 유고 시 출석하게 하는 자는?', '["참관인", "대리인", "변호인", "증인"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '변호인과 대리인의 가장 큰 차이점은?', '["변호인은 재판에 참석하고, 대리인은 참석하지 않는다.", "변호인은 피고를 위해, 대리인은 원고를 위해 활동한다.", "변호인은 유죄를 입증하고, 대리인은 무죄를 입증한다.", "변호인은 법률적 변호를, 대리인은 당사자의 출석 대행을 한다."]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '목사를 면직할 만한 죄 중 하나는?', '["예배에 지각하는 것", "개인적인 불만을 표현하는 것", "헌금을 적게 드리는 것", "이단을 주장하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '목사를 면직할 만한 또 다른 죄는?', '["목회에 열심이 부족한 것", "설교를 짧게 하는 것", "불법으로 교회를 분립하는 행동", "교인들과 갈등을 겪는 것"]'::jsonb, 2);
