insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '노회 재판국 국원 중 과반수는 누구로 정합니까?', '["장로", "권사", "집사", "목사"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '노회 재판국의 국원 선정 방식은?', '["추천을 통해", "자동 임명", "투표 선정", "추첨"]'::jsonb, 2);
