insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '총회 상설 재판국의 구성에서 목사 인원이 장로 인원보다 많은 주된 이유는?', '["교리적, 신학적 전문성을 요구하는 최상급 재판의 특성 때문", "총회 운영을 효율적으로 하기 위함", "장로의 책임감을 줄이기 위함", "목사의 권한을 강화하기 위함"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '특별 재판국이 다루는 사건의 특징은?', '["총회에서 이미 판결했으나 취소된 사건", "새롭게 제기된 사건", "간단한 행정 문제", "하회에서 해결하지 못한 사건"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '특별 재판국이 판결한 후 그 결과를 누구에게 보고해야 합니까?', '["노회", "본회(총회)", "당회", "제직회"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '특별 재판국 제도가 필요한 주된 이유는?', '["총회 본회에서 발생한 오판을 바로잡고 재심의의 전문성을 확보하기 위함", "총회 본회의 부담을 줄이기 위함", "모든 사건을 특별하게 처리하기 위함", "특정 국원들에게 권한을 집중하기 위함"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판국원이 그 재판에 대하여 투표권을 상실하게 되는 경우 중 하나는?', '["재판에 너무 열심히 참여할 때", "재판 진행에 적극적으로 기여할 때", "재판에 대한 개인적인 의견이 있을 때", "재판할 때 결석한 회원(국원)"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '지각이나 조퇴로 자초지종 임석하지 못한 회원(국원)은 어떻게 됩니까?', '["투표권을 상실한다.", "부분적으로 투표권을 행사할 수 있다.", "다음 재판에 자동으로 참여한다.", "특별히 배려한다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판국원이 투표권을 상실하는 또 다른 경우는?', '["원피고와 재판회(국)의 동의 승낙을 얻지 못한 회원(국원)", "재판국장의 지시를 따르지 않는 회원", "원피고와 재판회(국)의 동의 승낙을 얻은 회원(국원)", "재판 결과에 불만을 가진 회원"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판국원의 투표권 상실 규정이 중요한 이유는?', '["특정 국원에게 특혜를 주기 위함", "재판 진행을 지연시키기 위함", "재판의 공정성과 투명성을 확보하고, 재판 과정에 온전히 참여한 자만이 판단에 참여하도록 하기 위함", "국원들의 부담을 줄이기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '치리회가 재심 청구를 거절할 수 있는 경우는?', '["재심을 통해 새로운 사실이 밝혀질 가능성이 있을 때", "재심에서 면죄할 만한 새 증거가 나타날 것이라 여겨지지 아니하면", "피고가 재심을 강력히 요구할 때", "재심 절차가 복잡할 때"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재심 청구 거절의 주된 이유는?', '["재판국의 부담을 줄이기 위함", "재판의 종결성을 보장하기 위함", "불필요한 반복 소송으로 교회의 행정을 낭비하지 않기 위함", "피고의 권리를 침해하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재심 청구를 거절할 수 있다는 규정은 무엇을 강조합니까?', '["재판의 최종적 성격", "피고의 권리 제한", "치리회의 독단적 권한", "재심의 필요성"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재심 청구를 거절하기 전에 치리회가 고려해야 할 사항은?', '["재심에 대한 교인들의 여론", "새로운 증거의 유무와 그 증거가 판결을 뒤집을 만한 중요성을 가지는지 여부", "피고의 경제적 능력", "재심으로 인한 교회의 이미지 손상 여부"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '정직되었던 장로가 직무를 회복하기 위해 가장 먼저 해야 할 일은?', '["회개", "봉사 활동 참여", "교인들에게 사과", "헌금 증액"]'::jsonb, 0);
