insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '장로의 직무 복직 시 교인의 가부를 기다릴 필요가 있습니까?', '["있다", "없다", "노회의 지시에 따른다", "공동의회 결의가 필요하다"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '정직되었던 장로의 직무 회복 절차가 가지는 의미는?', '["정직 처분이 가볍다는 것을 의미한다.", "교인의 의견은 중요하지 않다.", "회개와 당회의 판단을 통해 교회의 질서 안에서 직무를 회복할 기회를 준다는 의미이다.", "장로의 직무는 언제든지 복직 가능하다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 장로가 복직을 위한 첫 절차로 무엇을 해야 합니까?', '["회개", "공동의회에 출석", "교회에 재정 기부", "노회에 탄원서 제출"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 장로가 회개하면 당회의 결의로 무엇을 해벌하고 성찬에 참여케 합니까?', '["견책", "정직", "출교", "면직"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 장로가 다시 임직을 받기 위해 필요한 절차는?', '["자동으로 복직된다.", "교회가 다시 투표하여 장립 예식을 행한 후에 임직이 가능하다.", "1 년 동안 봉사하면 자동 임직된다.", "노회의 지시만 받으면 된다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사가 복직할 수 있는 곳은?', '["총회", "노회", "면직한 치리회 앞에서 복직하거나, 그 회의 결의대로 위탁받은 치리회", "당회"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사의 복직은 누가 최종적으로 허락합니까?', '["총회장", "해당 지교회 당회", "면직 처분을 내렸던 치리회", "교인 전체"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사가 복직하기 위해 가장 먼저 필요한 것은?', '["새로운 신학교 졸업", "교인들의 동의", "재정적 보상", "진정한 회개"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사의 복직 절차가 엄격한 주된 이유는?', '["목사의 편의를 위함", "목사직의 중요성과 면직 처분의 중대성을 반영하여 신중한 절차를 거치기 위함", "목회자의 명예를 훼손하기 위함", "다른 교회로 가지 못하게 하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '당회 재판 없이 즉시 처결할 수 있는 경우 중 하나는?', '["교인들이 봉사 활동을 요청할 때", "목회자가 성경 공부를 지도할 때", "교인이 개인적인 고민을 토로할 때", "치리회 석상에서 범죄한 사건"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '당회 재판 없이 즉시 처결할 수 있는 또 다른 경우는?', '["증거가 불충분할 때", "범죄가 경미한 경우", "타처에서 범죄한 것을 본인이 자복했을 때", "범죄 사실이 복잡할 때"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '즉결 처단 제도가 필요한 주된 이유는?', '["재정적인 부담을 줄이기 위함", "명백한 범죄에 대해 신속하게 교회의 질서를 회복하고 죄악에 대한 단호한 입장을 표명하기 위함", "모든 재판 과정을 생략하기 위함", "교회의 명예를 보호하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '위탁 판결을 하는 주된 이유는 무엇입니까?', '["재판을 피하기 위함", "본 회의에서 결정하기 어려운 재판 사건에 대하여 지도를 구하는 것", "모든 재판을 상회에 맡기기 위함", "하회의 책임을 회피하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '위탁 판결은 하회의 어떤 면을 보완하기 위한 제도입니까?', '["권한 부족", "구성원 부족", "책임감 부족", "전문성 또는 판단의 어려움"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소는 하회에서 판결한 어떤 사건에 대하여 서면으로 상회에 제출하는 것입니까?', '["재판 사건", "인사 문제", "행정 사건", "재정 문제"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소는 하회의 판결에 대해 무엇을 구하는 절차입니까?', '["보고", "재심 또는 변경", "승인", "감사"]'::jsonb, 1);
