insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '공소와 상고를 구분하는 가장 중요한 기준은?', '["상소하는 당사자", "재판의 결과", "상소하는 하회와 심의하는 상회", "재판의 내용"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '소원이란 무엇을 요구하는 행정 소송입니까?', '["행정 처리의 취소나 변경이나 촉구", "책벌", "직분 임명", "재정 지원"]'::jsonb, 0);
