insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '소원이 ''요구서가 아니라 행정 처리의 취소나 변경이나 촉구를 요구하는 행정 소송''이라는 것은 무엇을 강조합니까?', '["소원이 교인의 의견 표출 수단임을 강조한다.", "소원이 행정적 불합리에 대한 시정 요구임을 강조한다.", "소원이 권징의 수단임을 강조한다.", "소원이 재판 사건임을 강조한다."]'::jsonb, 1);
