insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '행정 처결의 촉구, 변경, 취소 등을 요구하는 소원에 대한 최후 결정은 무엇입니까?', '["판결문", "보고서", "심의서", "결정서"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '판결문과 결정서의 가장 큰 차이점은?', '["판결문은 하회에서, 결정서는 상회에서만 발행된다.", "판결문은 공개되고, 결정서는 비공개이다.", "판결문은 책벌 요구에 대한 재판 결과이고, 결정서는 행정 소원에 대한 결과이다.", "판결문은 행정건에, 결정서는 재판건에 사용된다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '이 두 문서의 차이를 명확히 하는 이유는?', '["문서의 종류를 늘리기 위함", "책임 소재를 불분명하게 하기 위함", "행정 편의를 위함", "재판과 행정의 성격을 구분하고, 각 결정의 법적 효력과 의미를 명확히 하기 위함"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '범죄 발각 후 고소를 제기할 수 있는 일반적인 기간은?', '["6 개월", "1 년", "2 년", "3 년"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '교회에 중대한 영향을 끼칠 만한 사건의 경우, 범죄 발각 후 고소를 제기할 수 있는 기간은?', '["1 년", "2 년", "3 년", "5 년"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '범죄에 대한 고소 제기 기간을 제한하는 주된 이유는?', '["범죄자를 보호하기 위함", "모든 사건을 빨리 종결하기 위함", "시간이 경과함에 따라 증거 확보가 어려워지고, 관계 회복의 기회를 주기 위함", "교회의 부담을 줄이기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''교회에 중대한 영향을 끼칠 만한 사건''에 더 긴 공소시효를 두는 이유는?', '["중대 범죄는 그 파급력이 커서 더 오랜 기간 심의와 처벌의 필요성이 인정되기 때문", "사회 법률을 따르기 위함", "더 많은 증거를 찾기 위함", "중요하지 않은 사건은 빨리 잊기 위함"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '결정에 동의하지 아니함을 밝히는 것은 무엇입니까?', '["상소", "이의", "항의", "소원"]'::jsonb, 1);
