insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''이의''를 제기하는 주된 목적은?', '["회의 진행을 방해하기 위함", "결정의 내용을 바꾸기 위함", "특정 결정에 대한 자신의 비동의를 공식적으로 기록하고, 향후 불복의 기초를 마련하기 위함", "다른 사람들에게 자신의 의견을 강요하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''항의서''를 제출하는 주된 목적은?', '["단순한 불만을 표출하기 위함", "특정 결정이나 행위의 오류나 위법성을 증명하고 시정을 요구하기 위함", "회의에 참여하지 않기 위함", "개인적인 감정을 표현하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '예배모범은 무엇을 위한 규범입니까?', '["교인들 간의 친목을 도모하기 위함", "교회의 재정 관리를 위함", "하나님께 모범적인 예배를 드리기 위함", "모범적인 교회 건물을 짓기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '예배는 하나님의 무엇으로서, 사람이 하나님께 대한 최상의 자발적 복종 행위로 드리는 경배입니까?', '["심판", "계획", "섭리", "창조의 목적"]'::jsonb, 3);
