insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '''신령과 진정으로'' 드리는 예배가 강조하는 것은?', '["예배자의 외적 자세", "예배의 형식적 완벽함", "성령의 이끄심과 진리 안에서 드리는 마음의 중심", "예배 장소의 웅장함"]'::jsonb, 2);
