insert into public.exam_questions (subject, question, options, answer) values ('상식', '인간의학문은 삶의 의미, 존재의 본질, 지식의 기원 등 근본적인 질문들을 탐구하는무엇입니까?', '["역사", "종교", "과학", "철학"]'::jsonb, 3);
