insert into public.exam_questions (subject, question, options, answer) values ('상식', '고대 로마 제국이 공화정에서 제정으로 전환된 후, ''팍스 로마나'' 시대를 열며 지중해 세계를 지배했던 시기는 언제입니까?', '["콘스탄티누스 대제 시대", "아우구스투스 시대", "알렉산더 대왕 시대", "카이사르 시대"]'::jsonb, 1);
