insert into public.exam_questions (subject, question, options, answer) values ('상식', '제 1 차 세계대전 이후, 국제 평화와 협력을 위해 창설되었으나 한계를 보이다가 제 2 차 세계대전 이후 유엔으로 계승된 국제기구는 무엇입니까?', '["국제연맹 (League of Nations)", "국제연합 (UN)", "국제사법재판소 (ICJ)", "NATO"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '제 2 차 세계대전 이후 미국과 소련을 중심으로 이념과 군사적 대립이 격화되었던 시기를 무엇이라고 합니까?', '["탈냉전 시대", "정보화 시대", "냉전 시대", "세계화 시대"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '1960 년대 미국에서 마르틴 루터 킹 주니어 목사를 중심으로 인종 차별에 반대하고 평등을 주장했던 운동은 무엇입니까?', '["여성 인권 운동", "시민권 운동", "노동 운동", "환경 운동"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '1980 년대 후반부터 시작된 인터넷과 컴퓨터 기술의 발전으로 정보의 생산, 유통, 소비 방식이 혁신적으로 변화한 시대를 무엇이라고 합니까?', '["농업 사회", "정보화 사회", "산업 사회", "지식 기반 사회"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '다양한 정보를 비판적으로 분석하고 평가하며, 논리적으로 사고하여 합리적인 결론을 도출하는 능력을 무엇이라고 합니까?', '["암기력", "공감 능력", "창의력", "비판적 사고력"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '독서, 예술 감상, 여행 등을 통해 견문을 넓히고 인격을 함양하며, 삶의 질을 높이는 활동을 총칭하는 용어는 무엇입니까?', '["교양 활동", "여가 활동", "생계 활동", "사회 활동"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '개인의 삶에서 육체적, 정신적, 사회적 안녕이 조화롭게 이루어진 상태를 무엇이라고 합니까?', '["성공", "부유함", "건강", "행복"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '인터넷상에서 개인의 신분을 숨기고 악의적인 댓글이나 허위 정보를 유포하여 타인에게 피해를 주는 행위를 무엇이라고 합니까?', '["정보 공유", "사이버 불링", "선의의 비판", "정당한 주장"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '인공지능(AI), 빅데이터, 사물 인터넷(IoT) 등으로 대표되는 기술 발전이 사회 전반에 걸쳐 큰 변화를 가져오는 시대를 무엇이라고 합니까?', '["전기 시대", "증기기관 시대", "4 차 산업혁명 시대", "정보 통신 시대"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '지속 가능한 발전을 위해 환경 보호와 경제 성장을 동시에 추구하며, 미래 세대의 필요를 충족시키는 범위 내에서 현재의 발전을 이루려는 개념은 무엇입니까?', '["친환경 발전", "무제한 성장", "제로 성장", "환경 파괴"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '복잡한 현대 사회에서 다양한 의견과 가치를 가진 사람들이 서로를 이해하고 존중하며 대화하는 태도를 무엇이라고 합니까?', '["무관심", "고립주의", "소통과 공감", "극단주의"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '개인이 사회 구성원으로서 가지는 권리와 의무를 인식하고, 공동체의 발전에 적극적으로 참여하려는 태도를 무엇이라고 합니까?', '["시민 의식", "이기주의", "방관자적 태도", "무책임"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '기독교를 박해하던 로마 제국이 기독교를 공인하게 된 계기가 된 칙령은 무엇입니까?', '["테오도시우스 칙령", "니케아 칙령", "카노사 칙령", "밀라노 칙령"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '로마 제국 말기, 기독교를 국교로 선포한 로마 황제는 누구입니까?', '["아우구스투스", "네로", "테오도시우스 1 세", "콘스탄티누스 대제"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '초대 교회 시대, 기독교의 핵심 교리(예: 삼위일체, 그리스도의 신성)를 확립하기 위해 모였던 주교들의 회의를 무엇이라고 합니까?', '["종교개혁 회의", "십자군 회의", "종교재판", "에큐메니컬 공의회"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '기독교 박해 시기, 신앙을 지키기 위해 기꺼이 죽음을 택했던 이들을 무엇이라고 부릅니까?', '["사도", "순교자", "선지자", "교부"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '동방 교회(정교회)와 서방 교회(로마 가톨릭)가 분열된 사건을 무엇이라고 부릅니까?', '["아비뇽 유수", "종교개혁", "십자군 전쟁", "동서 교회의 대분열 (대분열)"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '교황의 권력이 절정에 달했던 시기에, 성지 탈환을 목적으로 교황의 주도하에 이루어진 대규모 원정은 무엇입니까?', '["십자군 전쟁", "대항해 시대", "백년 전쟁", "이슬람 정복 전쟁"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '중세 시대, 수도원에서 주로 이루어졌던 활동으로 교회의 영적 중심지 역할을 했던 것은 무엇입니까?', '["농업 생산", "학문 연구와 기도 생활", "정치적 권력 획득", "상업 활동"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '중세 스콜라 철학을 대표하며, "나는 이해하기 위해 믿는다"는 말을 남긴 신학자는 누구입니까?', '["토마스 아퀴나스", "안셀무스", "아벨라르", "아우구스티누스"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '교황의 권위가 약화되고 교황청이 프랑스 아비뇽으로 이전했던 사건을 무엇이라고 부릅니까?', '["동방교회 분열", "콘스탄츠 공의회", "아비뇽 유수", "카노사의 굴욕"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '1517 년, 마르틴 루터가 비텐베르크 성당 문에 95 개조 반박문을 붙이면서 시작된 역사적 사건은 무엇입니까?', '["계몽주의", "종교개혁", "르네상스", "프랑스 혁명"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '종교개혁의 5 대 솔라(Sola) 중, ''오직 성경으로만''을 의미하는 것은 무엇입니까?', '["Soli Deo Gloria", "Sola Gratia", "Sola Fide", "Sola Scriptura"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '존 칼빈이 제네바에서 신정 정치를 시행하고 개혁 신학을 체계화한 그의 대표 저서는 무엇입니까?', '["신학대전", "참된 기독교인의 삶", "루터의 95 개조 반박문", "기독교 강요"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '종교개혁 이후, 로마 가톨릭 교회가 내부 개혁을 추진하며 트리엔트 공의회를 개최하는 등 개신교에 대응했던 움직임을 무엇이라고 부릅니까?', '["교황권 강화 운동", "계몽주의 운동", "재세례파 운동", "반종교개혁 (가톨릭 개혁)"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '근대 유럽에서 신앙의 자유와 개인의 이성, 합리성을 강조하며 사회 전반에 큰 영향을 미친 사상 운동은 무엇입니까?', '["낭만주의", "산업혁명", "계몽주의", "르네상스"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '19 세기 말, 선교사들이 한국에 들어오면서 서양 문물과 함께 기독교가 전파된 후, 1907 년 평양에서 대규모 영적 부흥 운동이 일어난 것은 무엇입니까?', '["신사참배 거부 운동", "백만인 구령운동", "1 운동", "평양 대부흥 운동"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '일제강점기 시절, 한국 교회가 신앙의 정절을 지키기 위해 강요된 종교 행위인 무엇을 거부하며 저항했습니까?', '["신사참배", "창씨개명", "황국신민서사", "내선일체"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '해방 후 한국 전쟁을 겪으며 남북 분단이 고착화된 후, 한국 교회 내에서 신학적 입장 차이로 인해 여러 교단이 분열되었는데, 이는 어떤 가치를 강조했기 때문입니까?', '["순결함 (Purity)", "봉사 (Service)", "성장 (Growth)", "일치 (Unity)"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('상식', '한국 기독교가 사회 참여에 적극적으로 나섰던 대표적인 시기로, 1980 년대 민주화 운동에 많은 교회가 참여하고 인권 보호에 앞장섰던 것은 무엇을 보여줍니까?', '["교회의 세속화", "신앙과 사회 정의의 실천", "교회의 외형적 성장 추구", "교회의 정치적 중립"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '다음 영어 성경 이름 중 한글 명칭이 올바르게 짝지어진 것은?', '["Exodus - 신명기", "Leviticus - 레위기", "Numbers - 창세기", "Genesis - 민수기"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '다음 영어 성경 이름 중 한글 명칭이 올바르지 않게 짝지어진 것은?', '["Song of Songs - 아가", "Ecclesiastes - 예레미야애가", "Psalms - 시편", "Proverbs - 잠언"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '다음 신약 성경 이름 중 한글 명칭이 올바르게 짝지어진 것은?', '["Romans - 사도행전", "Acts - 로마서", "Ephesians - 빌립보서", "Galatians - 갈라디아서"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '다음 영어 성경 이름 중 한글 명칭이 올바르지 않게 짝지어진 것은?', '["1 Peter - 베드로후서", "Revelation - 요한계시록", "James - 야고보서", "Hebrews - 히브리서"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '사도신경에서 "creator of heaven and earth"에 해당하는 우리말 표현은?', '["하늘과 땅의 창조자", "천지를 만드신 아버지 하나님", "천지를 만드신 분", "하늘과 땅을 만드신 분"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '사도신경에서 "suffered under Pontius Pilate"에 해당하는 우리말 표현은?', '["본디오 빌라도 때문에 고통스러워하셨다", "본디오 빌라도 아래에서 고난받으셨다", "본디오 빌라도에게 고통을 받으셨다", "본디오 빌라도에게 고난을 받으사"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '사도신경에서 "he ascended into heaven"에 해당하는 우리말 표현은?', '["하늘에 오르사", "하늘로 승천하셨다", "그는 하늘로 올라가셨다", "그는 천국으로 오르셨다"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '사도신경에서 "the communion of saints"에 해당하는 우리말 표현은?', '["성도들의 친교", "성도들의 모임", "성도가 서로 교통하는 것", "성도들의 교제"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '주기도문에서 "hallowed be Your name"에 해당하는 우리말 표현은?', '["이름이 거룩히 여김을 받으시오며", "당신의 이름이 거룩히 여김을 받으소서", "당신의 이름은 칭송받으소서", "당신의 이름은 거룩하다"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '주기도문에서 "Your will be done on earth as it is in heaven"에 해당하는 우리말 표현은?', '["뜻이 하늘에서 이루어진 것 같이 땅에서도 이루어지이다", "당신의 뜻이 땅에서 하늘처럼 이루어지소서", "하늘에 있는 당신의 뜻이 땅에서도 실현되소서", "당신의 뜻이 하늘에서처럼 땅에서도 이루어지소서"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '주기도문에서 "Give us today our daily bread"에 해당하는 우리말 표현은?', '["우리에게 오늘날의 양식을 주소서", "오늘 우리에게 필요한 식량을 주소서", "우리에게 매일의 빵을 주소서", "오늘날 우리에게 일용할 양식을 주옵시고"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '주기도문에서 "but deliver us from the evil one"에 해당하는 우리말 표현은?', '["그리고 우리를 악의 존재로부터 구하소서", "그러나 우리를 악으로부터 구하소서", "다만 우리를 악한 자에게서 구하소서", "다만 악에서 구하옵소서"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '"7 Dear friends, let us love one another, for love comes from God."에 해당하는 우리말 표현은?', '["사랑하는 형제자매들아, 서로 사랑하자, 사랑은 하나님에게서 비롯된다.", "친애하는 벗들아, 서로 사랑합시다, 사랑은 하나님에게서 나옵니다.", "사랑하는 자들아, 우리가 서로 사랑하자, 사랑은 하나님께로부터 온 것이기 때문이다.", "사랑하는 친구들아, 서로 사랑하자, 사랑은 하나님께로부터 온다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '"8 Whoever does not love does not know God, because God is love."에 해당하는 우리말 표현은?', '["사랑하지 않는 자는 하나님을 알지 못한다, 왜냐하면 하나님은 사랑이시다.", "사랑하지 아니하는 자는 하나님을 알지 못하나니, 이는 하나님은 사랑이시기 때문이다.", "사랑하지 않는 사람은 하나님을 알 수 없다, 하나님은 곧 사랑이시기 때문이다.", "사랑이 없는 이는 하나님을 모른다, 하나님이 사랑이기 때문이다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '"9 This is how God showed his love among us: He sent his one and only Son into the world that we might live through him."에 해당하는 우리말 표현은?', '["이것이 하나님이 우리에게 사랑을 보이신 방법이다: 그분은 그의 유일한 아들을 세상에 보내어 우리가 그를 통해 생명을 얻게 하셨다.", "하나님이 우리 가운데 그의 사랑을 이렇게 보여주셨다: 그는 그의 독생자를 세상에 보내셔서 우리가 그를 통해 살게 하셨다.", "하나님께서 우리에게 이렇게 사랑을 보여주셨다: 그분은 외아들을 세상에 보내어 우리가 그로 인해 살도록 하셨다.", "하나님의 사랑이 우리에게 이렇게 나타났으니: 그가 그의 독생자를 세상에 보내심은 우리로 말미암아 그를 통하여 살게 하려 하심이라."]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('영어', '"10 This is love: not that we loved God, but that he loved us and sent his Son as an atoning sacrifice for our sins."에 해당하는 우리말 표현은?', '["이것이 사랑이다: 우리가 하나님을 사랑한 것이 아니라, 그가 우리를 사랑하시고 우리 죄를 위한 속죄 제물로 그의 아들을 보내신 것이다.", "이것이 곧 사랑이다: 우리가 하나님을 사랑해서가 아니라, 그분이 우리를 사랑하여 아들을 우리 죄를 위해 희생 제물로 주셨다.", "사랑은 이것이니: 우리가 하나님을 사랑한 것이 아니요, 하나님이 우리를 사랑하사 그의 아들을 우리 죄를 위한 화목 제물로 보내신 것이니라.", "참된 사랑은 이것이다: 우리가 하나님을 사랑한 것이 아니라, 그분이 우리를 사랑해서 그의 아들을 우리의 죄를 대속하는 희생물로 보내셨다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '사람의 제일 되는 목적은 무엇입니까?', '["자신의 행복을 추구하는 것", "하나님을 영화롭게 하는 것과 그를 영원토록 즐거워하는 것", "부와 명예를 얻는 것", "세상에 선한 영향을 미치는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''그를 영원토록 즐거워하는 것''은 무엇을 의미합니까?', '["하나님을 오락의 대상으로 삼는 것", "하나님으로 인해 세상의 즐거움을 누리는 것", "하나님과의 관계에서 기쁨을 누리며 영원히 교제하는 것", "하나님과 잠시 즐거운 시간을 보내는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '사람의 제일 되는 목적이 하나님을 영화롭게 하고 그를 즐거워하는 것이라는 고백은 인간의 삶에 어떤 방향성을 제시합니까?', '["인간 중심적인 삶", "자기만족적인 삶", "하나님 중심적인 삶", "세상적인 성공을 위한 삶"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '성경이 제일 요긴하게 교훈하는 것은 무엇입니까?', '["세상의 역사와 과학 지식", "사회적인 성공 전략", "사람이 하나님을 어떻게 믿을 것과 하나님께서 사람에게 요구하시는 본분", "부자가 되는 방법"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''사람이 하나님을 어떻게 믿을 것''이라는 교훈은 주로 무엇과 관련이 있습니까?', '["개인의 감정", "사회적인 규칙", "교리, 즉 하나님이 어떤 분이시며 어떤 일을 하셨는지", "교회의 전통"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''하나님께서 사람에게 요구하시는 본분''은 주로 무엇과 관련이 있습니까?', '["개인의 능력", "인간의 자유로운 선택", "도덕, 즉 인간이 어떻게 살아가야 하는지", "물질적인 봉사"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님의 신격에 계신 위는 몇 위(位)이십니까?', '["두 위(位)", "한 위(位)", "세 위(位)", "네 위(位)"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님의 신격에 계신 세 위는 누구이십니까?', '["천사, 성인, 인간", "성부, 성자, 성령", "창조주, 구원주, 심판주", "모세, 다윗, 예수"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '삼위 하나님은 본체는 하나요, 무엇이 동등하십니까?', '["역할과 사역", "나이와 지혜", "존재와 속성", "권능과 영광"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''삼위는 한 하나님이시며, 본체는 하나요''라는 고백은 삼위일체 교리의 어떤 측면을 강조합니까?', '["하나님의 무한성", "하나님의 전능성", "위격의 다양성", "본질의 단일성"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님의 예정은 무엇입니까?', '["세상의 우연한 사건", "인간의 자유로운 선택", "인간의 노력을 통한 계획", "그 뜻대로 하신 영원한 경륜"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님의 예정은 무엇을 위하여 되어 가는 일을 미리 정하시는 것입니까?', '["세상의 질서", "인간의 행복", "교회의 성장", "자신의 영광"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님의 예정이 ''영원한 경륜''이라는 것은 무엇을 의미합니까?', '["하나님의 계획이 시간의 제약을 받지 않는다는 것", "하나님의 계획은 인간의 노력에 따라 달라진다는 것", "하나님의 계획이 언제든지 변할 수 있다는 것", "하나님이 미래를 모르신다는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님의 예정 교리가 강조하는 것은 무엇입니까?', '["인간의 책임 있는 행동", "우연과 필연의 조화", "하나님의 절대적인 주권과 섭리", "인간의 자유 의지"]'::jsonb, 2);
