insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님이 사람을 ''남녀로'' 창조하셨다는 것은 무엇을 강조합니까?', '["인간의 사회적 역할 구분", "인간의 육체적인 한계", "인간의 번식 목적", "인간 창조의 완전성과 다양성"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '소요리 문답에서 정의하는 죄는 무엇입니까?', '["단순히 실수하는 것", "사회적인 법률 위반", "하나님의 법을 순종함에 부족한 것이나 혹 어기는 것", "다른 사람을 미워하는 감정"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '죄의 정의에 ''부족한 것''이 포함되는 것은 무엇을 의미합니까?', '["죄는 항상 적극적인 행동으로 나타난다.", "의도하지 않은 행동은 죄가 아니다.", "율법을 완전히 지키지 못하는 것도 죄에 해당한다.", "인간은 완벽하지 않으므로 부족함은 죄가 아니다."]'::jsonb, 2);
