insert into public.exam_questions (subject, question, options, answer) values ('소요리', '죄의 정의가 ''하나님의 법''을 기준으로 하는 주된 이유는 무엇입니까?', '["인간의 기준이 모호하기 때문", "죄를 객관적으로 평가하기 위함", "죄가 하나님과의 관계에서 비롯된 것이기 때문", "죄의 심각성을 강조하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님이 택하신 자의 유일한 구원자는 누구입니까?', '["천사", "목사", "선지자", "주 예수 그리스도"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '주 예수 그리스도는 하나님의 어떤 분이십니까?', '["하나님의 영원한 아들", "하나님의 피조물 중 하나", "하나님의 대리자", "인간의 위대한 지도자"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도는 사람으로 오셨는데, 그 후로 한 위(位)에 두 가지 특수한 성품이 영원토록 어떻게 존재하십니까?', '["구원자이시오, 심판자이다", "사람이시오, 천사이다", "하나님이시오, 사람이시다", "하나님이시오, 영이시다"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''한 위(位)에 두 가지 특수한 성품''이라는 것은 그리스도의 어떤 교리를 나타냅니까?', '["단성론", "양성론 (그리스도의 신성과 인성)", "삼위일체론", "예정론"]'::jsonb, 1);
