insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도는 어떻게 잉태되어 탄생하셨습니까?', '["성령의 권능으로 동정녀 마리아에게", "하나님의 직접적인 창조로", "천사의 능력으로", "인간적인 방법으로"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도가 탄생하셨을 때 어떤 특징이 있으셨습니까?', '["육체적인 고통이 없으셨다.", "죄를 가지고 탄생하셨다.", "죄는 없으셨다.", "인간적인 약점이 많으셨다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도께서 우리의 구속자로 행하시는 직분은 무엇입니까?', '["선지자, 제사장, 왕", "창조자, 보존자, 심판자", "재판관, 군인, 목자", "교사, 의사, 왕"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도께서 이 세 직분을 행하시는 지위는 무엇입니까?', '["영원히 높은 지위에서만", "낮아지시고 높아지신 지위에서", "오직 세상의 지위에서만", "제사장 지위에서만"]'::jsonb, 1);
