insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도의 왕의 직분에서 ''우리를 다스리신다''는 것은 무엇을 의미합니까?', '["말씀과 성령으로 우리의 삶을 인도하고 다스리시는 영적인 통치", "모든 사람에게 명령을 내리는 것", "강압적인 통치", "세상의 정치적 권력을 장악하는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도께서 ''자기와 우리의 모든 원수를 막아 이기시는 것''은 누구에 대한 궁극적인 승리를 의미합니까?', '["인간적인 대적자들", "질병과 가난", "자연재해", "죄, 사탄, 사망"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '구속에 참여하는 데 있어서 인간의 역할은 무엇입니까?', '["성령의 부르심에 대한 믿음의 응답", "수동적인 기다림", "자신의 공로를 쌓는 것", "구속의 대가를 지불하는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''효력 있게 그리스도에게 연결되게 하여 주시는 일''은 무엇을 강조합니까?', '["구원이 의식적인 행위로 가능하다는 것", "구원이 오직 은혜로 말미암는다는 것", "구원이 자동적으로 이루어진다.", "구원이 인간의 노력으로 가능하다는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '성령께서 그리스도께서 성취한 구속을 우리에게 어떻게 적용시켜 주십니까?', '["우리의 육체적인 능력을 강화함으로", "우리 안에 믿음을 일으키시고, 또 효력 있는 부름으로써 우리를 그리스도와 연합하게 하는 것", "우리의 지식을 풍부하게 함으로", "우리 안에 재물을 주심으로"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '구속 적용에 있어서 성령의 첫 번째 역할은 무엇입니까?', '["우리에게 선한 행위를 하게 하는 것", "우리의 죄를 대신 갚는 것", "우리 안에 믿음을 일으키는 것", "우리에게 영적인 지식을 주는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '구속 적용의 궁극적인 결과는 무엇입니까?', '["물질적인 풍요", "개인적인 만족", "그리스도와 연합하는 것", "세상에서의 성공"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '의롭다 하심은 어떤 행위입니까?', '["세상의 법률적인 선언", "하나님의 거저 주신 은혜의 행위", "인간의 선한 행위", "교회의 권한으로 주어지는 행위"]'::jsonb, 1);
