insert into public.exam_questions (subject, question, options, answer) values ('소요리', '양자 삼는다는 것은 어떤 행위입니까?', '["사회적인 입양 절차", "인간의 선한 행위", "하나님이 거저 주신 은혜의 행위", "교회의 권한으로 주어지는 행위"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '양자 삼으심을 통해 하나님께서 하시는 일은 무엇입니까?', '["우리를 하나님의 자녀의 수효 중에 들게 하시며, 그 모든 특권을 우리에게 주시는 것", "우리에게 세상적인 부를 주는 것", "우리를 육체적으로 건강하게 하는 것", "우리의 사회적 지위를 높이는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '양자 삼으심의 결과로 우리는 무엇에 참여하게 됩니까?', '["천사의 특권", "하나님의 자녀의 수효", "인간적인 영광", "세상의 권력"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '양자 삼으심이 ''거저 주신 은혜의 행위''라는 것은 무엇을 강조합니까?', '["양자 됨은 우리의 자격으로 얻어진다.", "인간의 노력이 중요하다.", "양자 됨은 비용이 들지 않는다.", "하나님은 무조건적인 사랑을 베푸신다."]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '거룩하게 하심은 어떤 역사입니까?', '["인간의 노력으로 이루는 역사", "거저 주신 은혜의 역사", "세상의 윤리적 개선", "교회의 의식으로 이루는 역사"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '거룩하게 하심을 통해 우리는 무엇을 좇아 인격이 새로워집니까?', '["교회의 지도", "인간의 이상", "세상의 기준", "하나님의 형상"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''거저 주신 은혜의 역사''라는 표현은 무엇을 강조합니까?', '["거룩함은 구원과 무관하다.", "거룩함이 하나님의 주권적인 사역임을 강조한다.", "거룩함은 인간의 노력으로만 가능하다.", "인간의 선행이 중요하다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '십계명의 대강령은 무엇입니까?', '["우리의 마음을 다하고 성품을 다하고 뜻을 다하고 힘을 다하여 주 하나님을 사랑하고 또 이웃 사랑하기를 네 몸과 같이하라 하신 것", "모든 계명을 지키는 것", "죄를 짓지 않는 것", "선한 행위를 많이 하는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '대강령에서 ''주 하나님을 사랑하라''는 것은 무엇을 강조합니까?', '["마음과 성품과 뜻과 힘을 다하는 전인격적인 사랑", "예배에 참석하는 것만을", "하나님을 두려워하는 것만을", "하나님께 순종하는 것만을"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '대강령에서 ''이웃 사랑하기를 네 몸과 같이하라''는 것은 무엇을 강조합니까?', '["이웃 사랑이 선택 사항이다.", "자기 자신을 돌보는 것만큼 이웃을 사랑해야 한다.", "자신보다 이웃을 더 사랑해야 한다.", "이웃의 모든 요구를 들어줘야 한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 1 계명이 명하는 것은 무엇입니까?', '["하나님을 부정하는 것", "하나님을 위해 재물을 쌓는 것", "하나님은 유일하신 참 신이 되심과 우리의 하나님 되심을 알고 승인하며, 그대로 그에게 경배하며 영화롭게 하라 하신 것", "다른 신들을 용납하는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''유일하신 참 신''이신 하나님께 ''경배하며 영화롭게 하라''는 것은 무엇을 의미합니까?', '["하나님을 자신의 목적을 위한 수단으로 삼는 것", "하나님께 형식적인 예배를 드리는 것", "하나님을 두려워하지 않는 것", "오직 하나님만을 삶의 중심에 두고 예배하며 찬양하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 1 계명을 어기는 행위는?', '["성경을 읽지 않는 것", "하나님 외에 다른 것을 숭배하거나 하나님보다 더 사랑하는 것", "교회에 출석하지 않는 것", "헌금하지 않는 것"]'::jsonb, 1);
