insert into public.exam_questions (subject, question, options, answer) values ('소요리', '매 주의 첫날은 무엇이라고 부릅니까?', '["창조의 안식일", "유대인의 안식일", "그리스도인의 안식일", "모세의 안식일"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '안식일이 첫째 날로 변경된 가장 큰 신학적 근거는?', '["성령 강림", "사도들의 편의", "교회의 성장", "그리스도의 부활"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 5 계명이 명하는 것은 무엇입니까?', '["각 사람에게 속한 자기들의 지위와 인륜 관계, 즉 상하와 평등을 따라 높일 자를 높이고 의무를 다 하라 하신 것", "거짓 증거하지 말라", "간음하지 말라", "살인하지 말라"]'::jsonb, 0);
