insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''높일 자를 높이고 의무를 다 하라''는 것은 무엇을 강조합니까?', '["질서와 존중을 바탕으로 한 책임 있는 관계", "모든 권위에 무조건 복종하는 것", "자신의 지위를 강조하는 것", "사회적인 계급을 유지하는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 5 계명을 어기는 행위는?', '["권위를 가진 자를 무시하거나 자신의 위치에서 마땅히 해야 할 의무를 다하지 않는 것", "나이 많은 사람에게 불손한 태도를 보이는 것", "상사에게 불순종하는 것", "부모를 공경하지 않는 것"]'::jsonb, 0);
