insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 7 계명에서 ''정조를 보존하라''는 것은 주로 무엇과 관련이 있습니까?', '["사회적인 명예", "재정적인 청렴", "육체적인 순결만을", "성적인 순결과 관련된 모든 생각, 말, 행동"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 7 계명이 자신과 ''이웃의 정조''를 보존하라고 하는 것은 무엇을 강조합니까?', '["이웃에게 성적인 책임을 전가하는 것", "이웃의 사생활을 감시하는 것", "자신의 순결뿐 아니라 타인의 성적인 순결도 존중하고 보호해야 함을", "개인의 순결만을 지키는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '제 7 계명을 어기는 행위는?', '["폭력을 행사하는 것", "간음하거나, 음란한 생각, 말, 행동을 하는 것", "거짓말하는 것", "도둑질하는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도를 믿는다는 것은 무엇입니까?', '["구원의 은혜인데, 이로 말미암아 복음으로 자기를 우리에게 주신 대로 구원받기 위해 우리가 예수를 영접하고 그에게만 의지하는 것", "교회에 꾸준히 출석하는 것", "종교적인 지식을 쌓는 것", "선한 행위를 많이 쌓는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도를 믿는 것의 본질은 무엇입니까?', '["종교적인 감정적 체험", "그분을 구주로 영접하고 전적으로 의지하는 것", "단순한 지식적 동의", "사회적인 소속감"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도를 믿는 것이 ''구원의 은혜''라는 것은 무엇을 강조합니까?', '["믿음은 인간의 노력으로 얻어진다.", "믿음은 재정적인 보상을 가져온다.", "믿음은 하나님의 선물이며 인간의 공로가 아니다.", "믿음은 구원과 무관하다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''복음으로 자기를 우리에게 주신 대로'' 예수를 영접한다는 것은 무엇을 의미합니까?', '["복음이 제시하는 그리스도의 본질(구원자, 주)을 있는 그대로 받아들이는 것", "복음에 대해 비판적인 태도를 갖는 것", "복음을 듣는 즉시 무조건적으로 믿는 것", "복음의 모든 내용을 우리의 방식대로 이해하고 받아들이는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '생명에 이르는 회개는 어떤 은혜입니까?', '["잠시 후회하는 은혜", "세상적인 복을 받는 은혜", "구원의 은혜", "인간의 노력으로 얻는 은혜"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '생명에 이르는 회개를 통해 죄인이 자기 죄를 바로 알고 누구 안에서 하나님의 자비를 깨닫습니까?', '["인간의 노력 안에서", "교회의 전통 안에서", "세상의 지혜", "그리스도 안에서"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '회개의 결과로 죄인은 어떻게 되는 것입니까?', '["죄를 잊어버린다.", "죄를 합리화한다.", "죄를 반복한다.", "죄에 대하여 슬퍼하고 미워하고, 그 죄에서 떠나 하나님께로 돌아가서 굳은 결심과 노력으로 새롭게 순종하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '생명에 이르는 회개가 ''구원의 은혜''라는 것은 무엇을 강조합니까?', '["회개는 구원과 무관하다.", "회개는 죄인이 죄를 짓는 것을 멈추는 행위이다.", "회개는 구원에 필수적인 하나님의 주권적인 선물이다.", "회개는 인간의 의지로만 가능하다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '신약의 성례는 무엇입니까?', '["세례와 성찬", "침례와 성유", "안수와 혼례", "고해성사와 견진성사"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '신약의 성례가 구약의 의식들과 구별되는 주된 이유는 무엇입니까?', '["더 복잡한 절차를 가지고 있다.", "예수 그리스도의 성취된 구속 사역을 기념하고 적용한다.", "더 많은 사람들에게 베풀어진다.", "물질적인 복을 약속한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '성례가 ''표징''으로서의 의미를 가지는 것은 무엇을 나타냅니까?', '["성례 자체가 구원을 주는 힘", "눈에 보이는 형태로 영적인 진리를 상징하고 보여줌", "성례가 비밀스러운 의식임을", "성례가 인간의 공로를 나타냄을"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '세례가 의미하는 것은 무엇입니까?', '["죄를 지을 수 있는 권한을 받는 것", "우리가 그리스도에게 접붙임 되는 것과 은혜의 계약의 여러 가지 유익에 참여하는 것과 주님의 사람이 되기로 약속하는 것을 의미하며 인치는 것", "육체적인 정결함만을 의미하는 것", "교회 직분을 임명받는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '세례를 통해 우리는 무엇에 참여함을 인칩니까?', '["인간적인 공로", "세상의 부와 명예", "은혜의 계약의 여러 가지 유익", "자연적인 축복"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '세례가 ''주님의 사람이 되기로 약속하는 것''이라는 것은 무엇을 강조합니까?', '["세례는 하나님과의 언약적 관계 속에서 순종의 삶을 살겠다고 고백하는 서약이다.", "세례는 개인적인 선택일 뿐이다.", "세례는 교회 가입을 위한 형식적인 절차이다.", "세례 후에는 모든 죄에서 해방된다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '성찬을 합당하게 받는 자들은 무엇으로 그리스도의 몸과 피에 참여합니까?', '["지식", "의지", "육체와 정욕", "믿음으로"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '성찬을 통해 합당하게 받는 자들이 얻는 유익은 무엇입니까?', '["세상에서의 성공", "신령한 양식을 먹고 은혜 속에서 장성하는 것", "개인적인 만족", "물질적인 부"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '기도는 무엇을 통해 우리의 소원을 하나님께 아뢰는 것입니까?', '["자신의 능력", "천사의 이름으로", "그리스도의 이름으로", "교회의 이름으로"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '기도의 내용에 포함되는 것은 무엇입니까?', '["자신의 욕심만", "다른 사람을 비난하는 것", "그의 뜻에 합당한 것들을 간구하고 죄를 자복하며 그의 자비를 감사하게 인식하는 것", "세상의 모든 문제 해결"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '기도에서 ''죄를 자복하며''라는 것은 무엇을 강조합니까?', '["자신의 죄를 인정하고 하나님께 용서를 구하는 것", "회개 없는 기도", "죄를 숨기는 것", "남의 죄를 고발하는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '기도에서 ''그의 자비를 감사하게 인식하는 것''은 무엇을 강조합니까?', '["자신의 공로를 자랑하는 것", "응답 여부와 상관없이 하나님의 선하심에 대한 감사의 태도", "하나님께 요구만 하는 것", "기도를 통해 물질적인 복을 받은 후에만 감사하는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '하나님께서 우리의 기도를 지도하시기 위해 주신 특별한 지침은 무엇입니까?', '["그리스도께서 자기 제자들에게 주신 기도(주기도문)", "개인적인 영적 체험", "교회의 전통적인 기도문", "세상의 지혜로운 격언"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''하나님의 모든 말씀이 우리가 기도를 어떻게 할 것인가를 가르쳐 주는 데 유용하다''는 것은 무엇을 강조합니까?', '["성경 외 다른 지침은 필요 없다.", "기도의 내용과 자세는 성경 전체를 통해 배울 수 있다.", "모든 기도는 성경 구절로만 이루어져야 한다.", "성경은 기도에 대한 구체적인 방법만 제시한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''주기도문''이 기도의 특별한 지침이 되는 주된 이유는?', '["가장 짧은 기도문이기 때문", "주기도문을 외워야만 응답받기 때문", "가장 많이 외우는 기도문이기 때문", "예수님께서 직접 가르쳐주신 기도의 모범과 원리가 담겨 있기 때문"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '주기도문이 기도의 ''법칙'' 또는 ''지침''이 된다는 것은 무엇을 의미합니까?', '["주기도문 외의 기도는 무효하다.", "주기도문만 외워야 한다.", "주기도문은 단순히 암기용이다.", "주기도문의 형식과 내용을 따라 기도해야 한다는 원리적 가르침이다."]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '주기도문의 서론은 무엇입니까?', '["\"우리를 시험에 들게 하지 마옵시고\"", "\"하늘에 계신 우리 아버지\"", "\"나라와 권세와 영광이\"", "\"오늘날 우리에게 일용할 양식을 주옵시고\""]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '''하늘에 계신 우리 아버지''라는 서론이 우리에게 교훈하는 것은 무엇입니까?', '["하나님은 멀리 계신 분이다.", "하나님은 우리를 도와주실 능력이 있는 아버지께 나아가는 자녀들처럼, 거룩한 모든 공경심과 확신을 가지고 하나님께 가까이 나아가야 한다.", "하나님은 무섭고 엄한 분이시다.", "하나님은 우리의 모든 것을 알고 계시므로 기도할 필요가 없다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '주기도문의 서론이 강조하는 기도의 태도는?', '["겸손과 불확신", "무관심과 냉담함", "거룩한 공경심과 확신", "두려움과 공포"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '주기도문의 서론이 ''우리 아버지''라고 지칭하는 것은 무엇을 나타냅니까?', '["개인적인 기도만 강조한다.", "하나님이 모든 인간의 아버지임을 강조한다.", "다른 사람들과 함께 기도하고, 다른 사람들을 위하여 기도할 것을 교훈한다.", "하나님이 특정 개인의 아버지임을 강조한다."]'::jsonb, 2);
